widget.solution:
import cmath


def is_stationary_ar2(phi1, phi2):
    d = cmath.sqrt(phi1 * phi1 + 4 * phi2)
    roots = [(phi1 + d) / 2, (phi1 - d) / 2]
    return all(abs(r) < 1 for r in roots)
